function v240y1Normalize(d){
 if(!d||!V240Y1_CASE_IDS.includes(d.case_id))return d;
 d.case_briefing=v240y1Briefing(d.case_briefing);
 d.pre_results=v240y1Cards(d.pre_results);
 d.context_cards=v240y1Cards(d.context_cards);
 return d;
}

function v240y1Briefing(x){
 if(x==null)return '';
 if(typeof x==='string')return x;
 if(Array.isArray(x))return x.map(v=>typeof v==='string'?v:String(v)).join(' · ');
 if(typeof x==='object')return Object.entries(x).map(([k,v])=>k+': '+String(v==null?'':v)).join(' · ');
 return String(x);
}

try{
 V240Y1_CASE_IDS.forEach(id=>{
   if(typeof DEEP_DIVE_MAP_V17!=='undefined' && DEEP_DIVE_MAP_V17[id])v240y1Normalize(DEEP_DIVE_MAP_V17[id]);
 });
 if(typeof DEEP_DIVE_CASES_V17!=='undefined' && Array.isArray(DEEP_DIVE_CASES_V17))DEEP_DIVE_CASES_V17.forEach(v240y1Normalize);
}catch(e){console.error('[MolPath '+V240Y1_VERSION+'] schema normalization failed',e)}
